import {createCipheriv,createDecipheriv,randomBytes,timingSafeEqual,createHash} from 'node:crypto';
const fail=(status,cause)=>Object.assign(Error(status===401?'Sign-in required':status===403?'Reporting access denied':'Identity service unavailable'),{status,...(cause?{cause}:{})});
const token=x=>typeof x==='string'&&x.length>0&&x.length<=3000&&!/[\x00-\x20\x7f]/.test(x);
async function boundedJson(response){let n=0,parts=[];for await(const chunk of response.body||[]){n+=chunk.length;if(n>65536)throw Error('Identity response too large');parts.push(chunk);}return JSON.parse(Buffer.concat(parts).toString('utf8'));}
export function createHostedAuth({supabaseUrl,publishableKey,cookieKey,membership,sessionActive,fetchImpl=fetch,now=Date.now,cookieName='__Host-matter_reporting'}){
 let url;try{url=new URL(supabaseUrl);}catch{throw Error('Invalid identity provider');}
 if(url.protocol!=='https:'||url.username||url.password||url.search||url.hash||url.pathname!=='/'||!token(publishableKey)||!Buffer.isBuffer(cookieKey)||cookieKey.length!==32||typeof membership!=='function'||typeof sessionActive!=='function'||!/^__Host-[A-Za-z0-9_-]+$/.test(cookieName))throw Error('Invalid hosted auth configuration');
 const secret=Buffer.from(cookieKey),base=url.origin,age=7*86400;
 const seal=value=>{const iv=randomBytes(12),cipher=createCipheriv('aes-256-gcm',secret,iv);cipher.setAAD(Buffer.from(cookieName));const data=Buffer.concat([cipher.update(JSON.stringify(value),'utf8'),cipher.final()]),encoded=Buffer.concat([iv,cipher.getAuthTag(),data]).toString('base64url');if(encoded.length>3800)throw Error('Session is too large');return `${cookieName}=${encoded}; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=${age}`;};
 const open=header=>{const entries=String(header||'').split(';').map(s=>s.trim()).filter(s=>s.startsWith(cookieName+'='));if(entries.length!==1||entries[0].length>3900)throw fail(401);try{const text=entries[0].slice(cookieName.length+1);if(!/^[A-Za-z0-9_-]+$/.test(text))throw Error();const b=Buffer.from(text,'base64url');if(b.toString('base64url')!==text||b.length<29)throw Error();const d=createDecipheriv('aes-256-gcm',secret,b.subarray(0,12));d.setAAD(Buffer.from(cookieName));d.setAuthTag(b.subarray(12,28));const x=JSON.parse(Buffer.concat([d.update(b.subarray(28)),d.final()]).toString('utf8'));if(!token(x.accessToken)||!token(x.refreshToken)||!Number.isSafeInteger(x.expiresAt)||x.expiresAt<=now()||!/^[A-Za-z0-9_-]{43}$/.test(x.csrf||''))throw Error();return x;}catch{throw fail(401);}};
 async function provider(route,options){let r;try{r=await fetchImpl(base+route,{...options,redirect:'error',signal:AbortSignal.timeout(10000)});}catch(e){throw fail(503,{diagnosticCategory:e?.name==='TimeoutError'||e?.name==='AbortError'?'identity-timeout':'identity-transport'});}if(r.redirected||!r.ok){await r.body?.cancel();throw fail(([401,403].includes(r.status)||(route.includes('grant_type=refresh_token')&&r.status===400))?401:503,{diagnosticCategory:r.status===429?'identity-rate-limit':r.status>=500?'identity-server-error':'identity-rejected'});}try{return await boundedJson(r);}catch{throw fail(503,{diagnosticCategory:'identity-invalid-response'});}}
 async function verify(accessToken){if(!token(accessToken))throw fail(401);const user=await provider('/auth/v1/user',{method:'GET',headers:{apikey:publishableKey,Authorization:'Bearer '+accessToken,Accept:'application/json'}});if(!user||typeof user.id!=='string'||!user.id||user.id.length>200||typeof user.email!=='string'||!user.email||user.email.length>320||user.is_anonymous!==false||typeof user.email_confirmed_at!=='string'||!Number.isFinite(Date.parse(user.email_confirmed_at)))throw fail(401);let claims;try{const parts=accessToken.split('.');if(parts.length!==3||!/^[A-Za-z0-9_-]+$/.test(parts[1]))throw Error();claims=JSON.parse(Buffer.from(parts[1],'base64url').toString('utf8'));if(claims.sub!==user.id||typeof claims.session_id!=='string'||!/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(claims.session_id))throw Error();}catch{throw fail(401);}const [activeResult,memberResult]=await Promise.allSettled([sessionActive({userId:user.id,sessionId:claims.session_id}),membership(user.id)]);if(activeResult.status==='rejected')throw fail(503,activeResult.reason);if(activeResult.value!==true)throw fail(401);if(memberResult.status==='rejected')throw fail(503,memberResult.reason);const member=memberResult.value;if(member?.active!==true||!['owner','reviewer','viewer'].includes(member.role))throw fail(403);return {id:user.id,email:user.email,role:member.role};}
 // Cache only a short in-flight rotation result; authorization is rechecked for every caller.
 const rotations=new Map();
 const due=session=>{try{const exp=JSON.parse(Buffer.from(session.accessToken.split('.')[1],'base64url').toString()).exp;return Number.isFinite(exp)&&exp*1000<=now()+60000;}catch{return false;}};
 async function issue({accessToken,refreshToken}){if(!token(accessToken)||!token(refreshToken))throw fail(401);const actor=await verify(accessToken),csrf=randomBytes(32).toString('base64url'),cookie=seal({accessToken,refreshToken,csrf,expiresAt:now()+age*1000});return {cookie,actor,csrf};}
 async function rotate(session){
  const key=createHash('sha256').update(JSON.stringify([session.accessToken,session.refreshToken,session.csrf])).digest('hex');
  for(const[k,v]of rotations)if(v.settled&&v.users===0&&v.until<=now())rotations.delete(k);
  let entry=rotations.get(key);
  if(!entry){if(rotations.size>=1000)throw fail(503);entry={until:Infinity,settled:false,users:0,promise:null};entry.promise=(async()=>{const result=await provider('/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:publishableKey,'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({refresh_token:session.refreshToken})});if(!token(result.access_token)||!token(result.refresh_token))throw fail(503);const next={accessToken:result.access_token,refreshToken:result.refresh_token,csrf:session.csrf,expiresAt:now()+age*1000};entry.until=now()+15000;entry.settled=true;return {session:next,cookie:seal(next)};})().catch(e=>{rotations.delete(key);throw e;});rotations.set(key,entry);}
  entry.users++;try{const result=await entry.promise;const actor=await verify(result.session.accessToken);return {actor,csrf:result.session.csrf,cookie:result.cookie};}finally{entry.users--;entry.until=now()+15000;}
 }
 async function resolve(header,explicitRefresh=false){const session=open(header);let actor;try{actor=await verify(session.accessToken);}catch(e){if(e.status!==401)throw e;return rotate(session);}if(due(session))return rotate(session);const roll=explicitRefresh||session.expiresAt-now()<6*86400000;return {actor,csrf:session.csrf,...(roll?{cookie:seal({...session,expiresAt:now()+age*1000})}:{})};}
 return {issue,authenticate:header=>resolve(header),refresh:header=>resolve(header,true),clearCookie:()=>`${cookieName}=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0`,csrfMatches(a,b){if(typeof a!=='string'||typeof b!=='string')return false;const x=Buffer.from(a),y=Buffer.from(b);return x.length===y.length&&timingSafeEqual(x,y);}};
}
